use std::sync::Arc;
use arrow_array::{Float64Array, RecordBatch};
use arrow_schema::{DataType, Field, Schema};
use vgi_rpc_client::RpcClient;

fn main() -> vgi_rpc_client::Result<()> {
    let mut client = RpcClient::connect(&["./target/debug/worker"])?
        .protocol("Calculator");
    let schema = Arc::new(Schema::new(vec![
        Field::new("a", DataType::Float64, false),
        Field::new("b", DataType::Float64, false),
    ]));
    let params = RecordBatch::try_new(schema, vec![
        Arc::new(Float64Array::from(vec![2.0])),
        Arc::new(Float64Array::from(vec![3.0])),
    ])?;
    let (result, _) = client.call_unary("add", &params, None)?;
    println!("{:?}", result.column(0)); // [5.0]
    Ok(())
}

