#pragma once
#include <arrow/api.h>
#include <vgi_rpc/arrow_utils.h>

inline auto params_schema() {
    return arrow::schema({
        arrow::field("a", arrow::float64(), false),
        arrow::field("b", arrow::float64(), false),
    });
}
inline auto result_schema() {
    return arrow::schema({
        arrow::field("result", arrow::float64(), false),
    });
}
inline auto values(double value) {
    arrow::DoubleBuilder builder;
    VGI_RPC_THROW_NOT_OK(builder.Append(value));
    return vgi_rpc::unwrap(builder.Finish());
}

#include "protocol.h"
#include <vgi_rpc/server.h>
#include <vgi_rpc/request.h>
#include <vgi_rpc/result.h>

int main() {
    auto server = vgi_rpc::ServerBuilder()
        .protocol("Calculator")
        .add_unary("add", params_schema(), result_schema(),
            [](const vgi_rpc::Request& req, vgi_rpc::CallContext&) {
                auto sum = req.get<double>("a") + req.get<double>("b");
                return vgi_rpc::Result::value(result_schema(), {values(sum)});
            })
        .build();
    server->run();
}

#include "protocol.h"
#include <vgi_rpc/client.h>
#include <iostream>

int main() {
    vgi_rpc::RpcClientOptions options;
    options.protocol = "Calculator";
    auto client = vgi_rpc::RpcClient::spawn({"./worker"}, options);
    auto params = arrow::RecordBatch::Make(
        params_schema(), 1, {values(2), values(3)});
    auto result = client.call_unary("add", params);
    auto sum = std::static_pointer_cast<arrow::DoubleArray>(
        result.batch->column(0));
    std::cout << sum->Value(0) << '\n'; // 5
    client.close();
}
